# =====================================================================  18 · BOSS 3
lesson(18, ("Бос арки 3: Майже дорослий", "Boss łuku 3: Prawie dorosły", "Arc 3 Boss: Almost a Grown-Up"), "Review: Present Continuous, some/any, much/many, Past Simple questions, comparatives, superlatives",
 ("Підсумок арки «Доросле життя». Один день Кевіна-«дорослого»: ванна, магазин, ялинка, вечеря. Твої відповіді англійською вирішують, чи справиться він.",
  "Podsumowanie łuku „Dorosłe życie”. Jeden dzień Kevina-„dorosłego”: łazienka, sklep, choinka, kolacja. Twoje odpowiedzi po angielsku decydują, czy sobie poradzi.",
  "The end of the arc “Life as a Grown-Up”. One day of grown-up Kevin: bathroom, shop, tree, dinner. Your answers in English decide if he can manage."),
 A3, ("🎓", ("Диплом дорослого", "Dyplom dorosłego", "The Grown-Up Diploma"), ("Ти пройшов(ла) третю арку.", "Przeszedłeś(-aś) trzeci łuk.", "You finished the third arc.")),
 [
  boss_gloss(("Повторення арки 3 · ключові слова", "Powtórka łuku 3 · kluczowe słowa", "Arc 3 review · key words"), (13, 14, 15, 16, 17)),
  quest("A grown-up's day. Make the right choices in English.", "s1",
   {"s1": ("Mom calls in Kevin's dream: “What are you doing?” What does he answer?",
           ("Ванна. Пара. Дзеркало.", "Łazienka. Para. Lustro.", "The bathroom. Steam. The mirror."),
           [("I'm brushing my teeth, Mom!", "s2", True, ("Present Continuous: I'm brushing.", "Present Continuous: I'm brushing.", "Present Continuous: I'm brushing.")),
            ("I brush my teeth now, Mom!", "s1b", False, ("Now → am + -ing.", "Now → am + -ing.", "Now → am + -ing."))]),
    "s1b": ("Try again. Which is right for now?", ("Друга спроба.", "Druga próba.", "Second try."),
            [("I'm taking a shower!", "s2", True, ("Так: I'm taking.", "Tak: I'm taking.", "Yes: I'm taking.")),
             ("I taking a shower!", "end_bad", False, ("Немає am.", "Brak am.", "Missing am."))]),
    "s2": ("At the supermarket the cashier asks about milk. What does Kevin say?",
           ("Каса. Підозрілий погляд.", "Kasa. Podejrzliwe spojrzenie.", "The checkout. A suspicious look."),
           [("There isn't any milk at home, so I need some.", "s3", True, ("Any (−), some (+).", "Any (−), some (+).", "Any (−), some (+).")),
            ("There isn't some milk, so I need any.", "s3", False, ("Навпаки! Але касирка все одно продає.", "Odwrotnie! Ale kasjerka i tak sprzedaje.", "The other way round! The cashier sells it anyway."))]),
    "s3": ("The police officer asks about the drugstore. Which question does he ask?",
           ("Вулиця. Лід. Поліцейський.", "Ulica. Lód. Policjant.", "The street. Ice. A police officer."),
           [("Did you pay for the toothbrush?", "s4", True, ("Did + базова форма.", "Did + forma podstawowa.", "Did + base form.")),
            ("Did you paid for the toothbrush?", "end_mid", False, ("Після did — pay.", "Po did — pay.", "After did use pay."))]),
    "s4": ("Kevin looks at his tree and his dinner. What does he say?",
           ("Ялинка. Свічка. Одна тарілка.", "Choinka. Świeca. Jeden talerz.", "The tree. A candle. One plate."),
           [("My tree is bigger than last year's, but family is the most important.", "end_good", True, ("Порівняння + найвищий ступінь!", "Stopień wyższy + najwyższy!", "Comparative + superlative!")),
            ("My tree is more big, and family is the importantest.", "end_mid", True, ("Зміст добрий, форма — ні.", "Sens dobry, forma nie.", "Good meaning, wrong forms."))])},
   {"end_good": (("Кінцівка: Справжній дорослий", "Zakończenie: Prawdziwy dorosły", "Ending: A Real Grown-Up"),
                 ("Кевін зрозумів: бути дорослим — це не лише свобода, а й турбота.", "Kevin zrozumiał: dorosłość to nie tylko wolność, ale i troska.", "Kevin understands: being a grown-up isn't just freedom, it's caring too."), True),
    "end_mid": (("Кінцівка: Майже дорослий", "Zakończenie: Prawie dorosły", "Ending: Almost a Grown-Up"),
                ("День вдався, але граматику ще треба підтягнути.", "Dzień się udał, ale gramatykę trzeba podszlifować.", "The day went well, but the grammar needs work."), True),
    "end_bad": (("Кінцівка: Ще дитина", "Zakończenie: Jeszcze dziecko", "Ending: Still a Kid"),
                ("Спробуй цей день ще раз.", "Spróbuj tego dnia jeszcze raz.", "Try this day again."), False)},
   ("Квест перевіряє всю граматику арки 3.", "Quest sprawdza całą gramatykę łuku 3.", "The quest checks all the grammar of Arc 3."), img="letter"),
  kitchen([("aftershave", "Dad puts it on after shaving"), ("receipt", "paper that shows what you paid"), ("thief", "a person who steals"),
           ("branch", "part of a tree"), ("microwave", "it heats food quickly"), ("candle", "it gives light and burns")],
          ("Шість слів арки 3.", "Sześć słów łuku 3.", "Six words of Arc 3.")),
  kitchen([("to get dressed", "to put your clothes on"), ("to put on", "to wear something new"), ("by accident", "not on purpose"),
           ("to drag", "to pull along the ground"), ("to miss", "to feel sad without someone")],
          ("Фрази арки 3.", "Wyrażenia łuku 3.", "Phrases of Arc 3.")),
  gram("Right now Kevin ____ the tree.", ["is decorating", "decorates", "decorate", "decorating"], 0,
       [("Так! Right now → is + -ing.", "Tak! Right now → is + -ing.", "Yes! Right now → is + -ing."),
        ("Звичка.", "Nawyk.", "A habit."), ("Без -s і без is.", "Bez -s i bez is.", "No -s and no is."), ("Без is.", "Bez is.", "Missing is.")],
       ("Повторення уроку 13.", "Powtórka lekcji 13.", "Review of lesson 13.")),
  gram("How ____ eggs did Kevin buy?", ["many", "much", "any", "lot"], 0,
       [("Так! Eggs — злічувані.", "Tak! Eggs — policzalne.", "Yes! Eggs are countable."),
        ("Much — для незлічуваних.", "Much — dla niepoliczalnych.", "Much is for uncountable nouns."), ("How any — помилка.", "„How any” — błąd.", "How any is wrong."), ("How lot — помилка.", "„How lot” — błąd.", "How lot is wrong.")],
       ("Повторення уроку 14.", "Powtórka lekcji 14.", "Review of lesson 14.")),
  note(("This tree is ____ (good) than the small one. → (1 слово)", "This tree is ____ (good) than the small one. → (1 słowo)", "This tree is ____ (good) than the small one. → (1 word)"),
       ["better"], ("Good → better.", "Good → better.", "Good → better.")),
  note(("It was ____ (bad) day of the trip. → (3 слова)", "It was ____ (bad) day of the trip. → (3 słowa)", "It was ____ (bad) day of the trip. → (3 words)"),
       ["the worst"], ("Bad → worse → the worst.", "Bad → worse → the worst.", "Bad → worse → the worst.")),
  timeline(["Kevin used Dad's aftershave", "he did the shopping", "he ran away with a toothbrush", "he bought a Christmas tree", "he had dinner for one"],
           ("Уся арка 3 — у п'яти подіях.", "Cały łuk 3 w pięciu wydarzeniach.", "The whole Arc 3 in five events.")),
  speak("I'm a grown-up now, but I miss my family.", ("Спокійно і чесно.", "Spokojnie i szczerze.", "Calmly and honestly.")),
 ])
